(function(global){
'use strict';
const A=global.Serein.content;
const safeArray=x=>Array.isArray(x)?x:[];
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
const validId=(D,id)=>D.practices.some(p=>p.id===id);
function normalize(raw,D){
 const memory={},choices={},progress={};
 for(const p of D.practices){
  const m=raw.practiceMemory?.[p.id];
  if(m&&typeof m==='object')memory[p.id]={duration:p.durations.includes(+m.duration)?+m.duration:null,pace:['3-3','4-6','5-5'].includes(m.pace)?m.pace:'4-6',noHolds:!!m.noHolds,external:!!m.external,relaxOnly:!!m.relaxOnly,visual:['photo','orb','text','map'].includes(m.visual)?m.visual:'photo',voice:!!m.voice,lessMotion:!!m.lessMotion,chime:!!m.chime};
  if(['helpful','later','exclude'].includes(raw.practiceChoices?.[p.id]))choices[p.id]=raw.practiceChoices[p.id];
 }
 for(const j of A.journeys)progress[j.id]=safeArray(raw.journeyProgress?.[j.id]).filter((n,i,x)=>Number.isInteger(n)&&n>=0&&n<j.steps.length&&x.indexOf(n)===i);
 const date=x=>Number.isFinite(Date.parse(x))?new Date(x).toISOString():new Date().toISOString();
 const feedback=safeArray(raw.feedback).filter(x=>x&&validId(D,x.practiceId)&&['Helpful','No change','Uncomfortable'].includes(x.result)).slice(-2000).map(x=>({id:String(x.id||global.crypto?.randomUUID?.()||('s-'+Date.now()+'-'+Math.random().toString(36).slice(2))),practiceId:x.practiceId,result:x.result,moment:Number.isInteger(x.moment)&&x.moment>=0&&x.moment<4?x.moment:1,date:date(x.date),before:[1,2,3,4,5].includes(+x.before)?+x.before:null,after:[1,2,3,4,5].includes(+x.after)?+x.after:null,persistent:x.persistent===true}));
 const savedPlans=safeArray(raw.savedPlans).filter(x=>x&&typeof x.text==='string'&&A.studios.some(s=>s.id===x.studio)).slice(-100).map(x=>({id:String(x.id||global.crypto?.randomUUID?.()||('s-'+Date.now()+'-'+Math.random().toString(36).slice(2))),studio:x.studio,text:x.text.slice(0,12000),date:date(x.date)}));
 const p=raw.preferences||{};
 return {practiceMemory:memory,practiceChoices:choices,feedback,journeyProgress:progress,savedPlans,comfort:{readingSize:['standard','large','extra'].includes(p.readingSize)?p.readingSize:'standard',theme:['light','night'].includes(p.theme)?p.theme:'light',readingWidth:!!p.readingWidth,focus:!!p.focus}};
}
function create(c){
 const {D,state,$,$$,esc,icon,openModal,closeModal,toast,persist,render,navigate,openPractice,download,chooseDuration,matchPractices,durationLabel}=c;
 const store=()=>c.store;
 let finder={step:0,moment:1,budget:120,style:'any',position:'any',silent:false},studio=null,journey=null,sessionMeta=null,pendingTeam=null,installPrompt=null,offlineReady=false,offlineBusy=false,offlineMessage='',registration=null,audioContext=null,chimePhase='';
 const sourceLinks=keys=>keys.map(k=>A.references[k]).filter(Boolean).map(r=>`<a class="source-link" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗<small>${esc(r.scope)}</small></a>`).join('');
 function applyComfort(){let p=store().preferences;document.body.dataset.reading=p.readingSize||'standard';document.body.dataset.theme=p.theme||'light';document.body.classList.toggle('comfortable-reading',!!p.readingWidth);document.body.classList.toggle('focus-mode',!!p.focus);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',p.theme==='night'?'#0A1826':'#10253A');}
 function comfortForm(){let p=store().preferences;return `<fieldset class="comfort-fields"><legend>Read comfortably</legend><label class="field-label" for="pref-reading">Text size</label><select id="pref-reading" class="field" name="readingSize">${[['standard','Standard'],['large','Large'],['extra','Extra large']].map(([v,l])=>`<option value="${v}" ${p.readingSize===v?'selected':''}>${l}</option>`).join('')}</select><label class="field-label" for="pref-theme">Appearance</label><select id="pref-theme" class="field" name="theme"><option value="light">HCA ivory</option><option value="night" ${p.theme==='night'?'selected':''}>HCA navy night</option></select><label class="check-label"><input type="checkbox" name="readingWidth" ${p.readingWidth?'checked':''}>Comfortable reading width</label><label class="check-label"><input type="checkbox" name="focus" ${p.focus?'checked':''}>Low-distraction layout · simplify decorative content</label></fieldset>`;}
 function comfortValues(fd){return {readingSize:String(fd.get('readingSize')||'standard'),theme:String(fd.get('theme')||'light'),readingWidth:fd.has('readingWidth'),focus:fd.has('focus')};}
 function eligible(options={}){return matchPractices(D.practices,{budget:store().preferences.time,style:store().preferences.style,...options}).filter(p=>store().practiceChoices[p.id]!=='exclude');}
 function rank(options={}){
  const moment=options.moment??state.moment;
  const preferred=[['ground','listen','desk'],['tide','handreset','ground'],['ground','listen','quietplace'],['release','winddown','listen']][moment]||[];
  return eligible(options).map(p=>{const fs=store().feedback.filter(f=>f.persistent&&f.practiceId===p.id);const fit=preferred.indexOf(p.id);return {p,score:(fit<0?0:9-fit*2)+(store().practiceChoices[p.id]==='helpful'?8:0)+(store().practiceChoices[p.id]==='later'?-5:0)+Math.min(5,fs.filter(f=>f.result==='Helpful').length)-Math.min(8,fs.filter(f=>f.result==='Uncomfortable').length*3)+(store().savedPractices.includes(p.id)?1:0)};}).sort((a,b)=>b.score-a.score).map(x=>x.p);
 }
 function recommend(){return rank()[0]||null;}
 function reason(p,budget,moment){const reasons=[`Fits ${D.moments[moment]?.title.toLowerCase()||'this moment'}`,p.selfPaced?'self-paced':`${durationLabel(chooseDuration(p,budget))} within your time`,p.breathFocus?'breath focus':p.movement?'gentle movement':'without breath focus'];if(store().practiceChoices[p.id]==='helpful')reasons.push('marked helpful for you');return reasons.join(' · ');}
 function finderOpen(){finder={step:0,moment:state.moment,budget:store().preferences.time,style:store().preferences.style,position:'any',silent:false};finderRender();}
 function finderRender(){
  const content=[
   `<p class="studio-question">What is happening around this pause?</p><div class="choice-grid">${D.moments.map((m,i)=>`<button class="choice-card ${finder.moment===i?'selected':''}" data-adv="finder-moment" data-value="${i}" aria-pressed="${finder.moment===i}"><strong>${m.title}</strong><span>${m.desc}</span></button>`).join('')}</div>`,
   `<p class="studio-question">How much time is available?</p><div class="choice-grid">${[[60,'One minute'],[120,'Two minutes'],[300,'Five minutes'],['self','My own pace']].map(([v,l])=>`<button class="choice-card ${String(finder.budget)===String(v)?'selected':''}" data-adv="finder-time" data-value="${v}" aria-pressed="${String(finder.budget)===String(v)}"><strong>${l}</strong><span>${v==='self'?'No countdown':'A short, optional pause'}</span></button>`).join('')}</div>`,
   `<p class="studio-question">What would feel comfortable?</p><label class="field-label" for="finder-style">Attention focus</label><select class="field" id="finder-style"><option value="any">Open to different practices</option><option value="nonbreath" ${finder.style==='nonbreath'?'selected':''}>Without breath focus</option><option value="ground" ${finder.style==='ground'?'selected':''}>Grounding only</option></select><label class="field-label" for="finder-position">Movement</label><select class="field" id="finder-position"><option value="any">Any suitable practice</option><option value="seated" ${finder.position==='seated'?'selected':''}>Seated practices</option><option value="still" ${finder.position==='still'?'selected':''}>Without guided movement</option></select><label class="check-label"><input id="finder-silent" type="checkbox" ${finder.silent?'checked':''}>Keep this pause silent</label><p class="small-note">These choices apply to this search. Your usual preferences stay available.</p>`
  ];
  let html;
  if(finder.step<3)html=`${stepMeter(finder.step,3)}${content[finder.step]}<div class="studio-footer"><button class="button button-quiet" data-adv="finder-back" ${finder.step===0?'disabled':''}>Back</button><button class="button button-teal" data-adv="finder-next">${finder.step===2?'Show my choices':'Continue'} →</button></div>`;
  else {let options={...finder,budget:finder.budget==='self'?'self':+finder.budget};let list=rank(options).slice(0,3);html=`<p class="eyebrow">YOUR CHOICES / ${D.moments[finder.moment].title}</p><p>Preference matches with a clear reason. Choose, adapt or leave any practice.</p><div class="finder-results">${list.map((p,i)=>`<article class="finder-result"><span class="result-number">0${i+1}</span><div><h3>${p.title}</h3><p>${esc(p.desc)}</p><p class="match-reason">${esc(reason(p,finder.budget==='self'?0:+finder.budget,finder.moment))}</p><div class="button-row"><button class="button button-teal" data-adv="finder-start" data-id="${p.id}">Explore ${durationLabel(chooseDuration(p,finder.budget==='self'?0:+finder.budget))} →</button><button class="text-button" data-adv="evidence" data-id="${p.id}">About this practice</button></div></div></article>`).join('')||'<div class="empty"><h3>No match for these choices.</h3><p>You can adjust the choices or restore a practice you previously excluded in My space.</p></div>'}</div><div class="button-row"><button class="button button-outline" data-adv="finder-back">Adjust choices</button><button class="text-button" data-adv="preferences-open">Manage practice choices →</button></div>`;}
  openModal('Find a pause that fits.',html);
 }
 function stepMeter(step,total){return `<div class="studio-meter"><span>STEP ${step+1} OF ${total}</span><div class="meter-track"><span style="width:${(step+1)/total*100}%"></span></div></div>`;}
 function homeExtras(){let j=A.journeys.find(x=>(store().journeyProgress[x.id]||[]).length>0&&(store().journeyProgress[x.id]||[]).length<x.steps.length)||A.journeys[0];return `<section class="advance-launch"><div><p class="eyebrow">A PERSONAL PATH THROUGH YOUR DAY</p><h2>Start with what you need.</h2><p>Three small choices. One practice with a clear reason.</p></div><button class="button button-teal" data-adv="finder">Help me choose ${icon('arrow')}</button></section><div class="section-heading"><div><h2>Put support into practice</h2><p>Rehearse, prepare and make your next step concrete.</p></div><button class="text-button" data-adv="studios-open">All six studios →</button></div><div class="studio-grid compact">${A.studios.slice(0,3).map(studioCard).join('')}</div><section class="journey-invitation"><div><p class="eyebrow">LEARN AT YOUR OWN PACE</p><h3>${j.title}</h3><p>${j.description}</p></div><button class="button button-outline" data-adv="journey" data-id="${j.id}">${(store().journeyProgress[j.id]||[]).length?'Continue my journey':'Explore this journey'} →</button></section>`;}
 function aboutHTML(id){let p=D.practices.find(p=>p.id===id),e=A.evidence[id];if(!p||!e)return '';let metric=e.stat||[String(p.steps.length),'guided steps','An editorial count of this practice’s steps, not a measured health outcome.'];return `<section class="evidence-intro"><p class="eyebrow">WHAT / WHY / WHEN / HOW / WHO</p><h3>${p.title}</h3><p>${esc(p.desc)}</p></section><div class="evidence-grid">${[['Why choose it?',e.why],['When might it fit?',e.when],['How to use it',e.how],['Who chooses?',`You decide whether it is suitable. ${p.safety}`]].map(([h,t])=>`<section><h4>${h}</h4><p>${esc(t)}</p></section>`).join('')}</div><div class="fact-card"><strong>${metric[0]}</strong><div><h4>${metric[1]}</h4><p>${metric[2]}</p></div></div><h4 class="source-heading">Background & scope</h4>${sourceLinks(e.refs)}<p class="small-note">Source mapping updated ${A.updated}. Original educational adaptation; not a clinically validated Serein program. Images are illustrative. You can pause, adapt or stop.</p>`;}
 function evidence(id){const p=D.practices.find(p=>p.id===id);if(p)openModal('Understand this practice.',aboutHTML(id)+`<div class="button-row"><button class="button button-teal" data-practice="${id}">Open practice →</button></div>`);}
 function evidenceButton(p){return `<button type="button" class="text-button practice-info" data-adv="evidence" data-id="${p.id}" aria-label="About ${esc(p.title)}">About this practice ${icon('book')}</button>`;}
 function resetFeedback(){sessionMeta={id:c.uid(),before:null,after:null,result:null,persistent:false,moment:state.moment};$('#player-feedback').innerHTML=`<p class="eyebrow">JUST NOTICE</p><h3>How was that for you?</h3><p>No particular response is required. You choose whether to keep feedback.</p><div class="feedback-choices">${['Helpful','No change','Uncomfortable'].map(r=>`<button data-adv="feedback" data-value="${r}" aria-pressed="false">${r}</button>`).join('')}</div><label class="field-label" for="session-after">Optional: how settled do you feel now?</label><select id="session-after" class="field"><option value="">Skip</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} · ${['Not settled','A little settled','Somewhat settled','Settled','Very settled'][n-1]}</option>`).join('')}</select><label class="check-label"><input type="checkbox" id="feedback-save">Save this feedback for personal insights in this browser</label><p class="small-note">Saved feedback is not encrypted. Without saving it lasts for this visit. Personal observations are not clinical scores.</p><p id="feedback-note" role="status"></p><div class="practice-preference-actions"><span>Suggest this practice:</span>${[['helpful','More often'],['later','Try another time'],['exclude','Do not suggest']].map(([v,l])=>`<button class="button button-outline" data-adv="practice-choice" data-id="${state.session.practice.id}" data-value="${v}">${l}</button>`).join('')}</div>`;}
 function preparePractice(p,explicitDuration){
  let m=store().practiceMemory[p.id],e=state.session;
  if(m){if(!explicitDuration&&m.duration)e.duration=m.duration;e.pace=m.pace;e.noHolds=m.noHolds;e.external=m.external;e.relaxOnly=m.relaxOnly;state.visual=(m.visual==='map'&&p.id!=='scan')?'photo':m.visual;state.voice=false;}
  resetFeedback();chimePhase='';
  $('#player-notes-content').innerHTML=aboutHTML(p.id);
  if(m){$('#session-duration').value=String(e.duration);if($('#session-pace'))$('#session-pace').value=e.pace;if($('#session-noholds'))$('#session-noholds').checked=e.noHolds;$('#session-external').checked=e.external;if($('#session-relax'))$('#session-relax').checked=e.relaxOnly;$('#session-visual').value=state.visual;$('#session-motion').checked=m.lessMotion||c.reduced();}
  $('#player-settings-content').insertAdjacentHTML('beforeend',`<label class="field-label" for="session-before">Optional: how settled do you feel before starting?</label><select id="session-before" class="field"><option value="">Skip</option>${[1,2,3,4,5].map(n=>`<option value="${n}">${n} · ${['Not settled','A little settled','Somewhat settled','Settled','Very settled'][n-1]}</option>`).join('')}</select><label class="check-label"><input type="checkbox" id="session-remember" ${m?'checked':''}>Remember timing, visual and comfort options for this practice</label><p id="memory-status" class="small-note">${m?'Your saved practice settings have been applied. Voice remains off until enabled.':'Options are temporary unless you choose to remember them.'}</p>`);
  $('#player-settings-content').insertAdjacentHTML('beforeend',`<label class="check-label"><input type="checkbox" id="session-chime" ${m?.chime?'checked':''}>Gentle phase-change tone · optional local audio</label>`);
  if(m?.voice){state.voice=false;$('#session-voice').checked=false;}
  if(pendingTeam){const t=pendingTeam;pendingTeam=null;e.noHolds=true;e.external=t.external;state.visual='text';$('#session-visual').value='text';$('#session-external').checked=t.external;if($('#session-noholds'))$('#session-noholds').checked=true;$('#session-motion').checked=true;$('#session-chime').checked=false;state.voice=false;$('#session-voice').checked=false;state.present=true;$('#player').classList.add('present');$('#present-button').setAttribute('aria-pressed','true');}
 }
 function rememberPractice(){if(!state.session||state.preview)return;let id=state.session.practice.id;if($('#session-remember')?.checked){store().practiceMemory[id]={duration:state.session.duration,pace:state.session.pace,noHolds:state.session.noHolds,external:state.session.external,relaxOnly:state.session.relaxOnly,visual:state.visual,voice:state.voice,lessMotion:!!$('#session-motion')?.checked,chime:!!$('#session-chime')?.checked};$('#memory-status').textContent='These practice options are remembered in this browser.';}else{delete store().practiceMemory[id];if($('#memory-status'))$('#memory-status').textContent='Practice options are temporary.';}persist();}
 function upsertFeedback(){if(!sessionMeta?.result||state.preview)return;const f={id:sessionMeta.id,practiceId:state.session.practice.id,result:sessionMeta.result,before:sessionMeta.before,after:sessionMeta.after,moment:sessionMeta.moment,date:sessionMeta.date||(sessionMeta.date=new Date().toISOString()),persistent:sessionMeta.persistent};let i=store().feedback.findIndex(x=>x.id===f.id);if(i<0)store().feedback.push(f);else store().feedback[i]=f;persist();}
 function feedback(value){if(!sessionMeta||state.preview)return;sessionMeta.result=value;sessionMeta.after=+$('#session-after').value||null;sessionMeta.persistent=$('#feedback-save').checked;upsertFeedback();$$('[data-adv="feedback"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===value);b.setAttribute('aria-pressed',String(b.dataset.value===value));});$('#feedback-note').textContent=(value==='Uncomfortable'?'Stop or choose another focus. Human support may be more useful. There is no need to continue. ':'Thank you for noticing. ')+(sessionMeta.persistent?'Saved in this browser for your insights.':'Kept for this visit only.');}
 function choosePreference(id,value){store().practiceChoices[id]=value;persist();toast(value==='exclude'?'Removed from recommendations. You can restore it in My space.':value==='later'?'Serein will give other practices priority.':'This practice will be given more priority when it fits.');if(!$('#player').open)render();}
 function preferencesHTML(){return `<section class="advance-panel"><div class="section-heading"><div><h2>Your practice choices</h2><p>Excluded practices remain accessible in the catalogue. You can restore suggestions here.</p></div></div><div class="preference-list">${D.practices.filter(p=>store().practiceChoices[p.id]||store().practiceMemory[p.id]).map(p=>`<div><span><strong>${p.title}</strong><small>${({exclude:'Not suggested',helpful:'Given more priority',later:'Try another time'})[store().practiceChoices[p.id]]||'Usual suggestion priority'}${store().practiceMemory[p.id]?' · Comfort options remembered':''}</small></span><button class="text-button" data-adv="restore-practice" data-id="${p.id}">Reset choices & memory</button></div>`).join('')||'<p>No practice choices or comfort options saved yet.</p>'}</div></section>`;}
 function insights(){
  const all=store().feedback.filter(f=>state.dateFilter==='all'||Date.now()-Date.parse(f.date)<=+state.dateFilter*86400000),saved=all.filter(f=>f.persistent),paired=all.filter(f=>f.before&&f.after),helpful=all.filter(f=>f.result==='Helpful').length;
  const groups=D.practices.map(p=>({p,fs:all.filter(f=>f.practiceId===p.id)})).filter(x=>x.fs.length);
  return `<section class="advance-panel"><p class="eyebrow">YOUR EXPERIENCE / YOUR INTERPRETATION</p><h2>What you chose to notice.</h2><p class="section-description">Feedback from the selected period. Visit-only entries are included until reload; ${saved.length} of ${all.length} are saved. Missing entries are unknown.</p><div class="insight-stats"><div><strong>${all.length}</strong><span>responses recorded</span></div><div><strong>${helpful}</strong><span>marked helpful</span></div><div><strong>${paired.length}</strong><span>optional before/after pairs</span></div></div>${groups.length?`<div class="feedback-bars">${groups.map(({p,fs})=>`<div><span>${p.title}</span><div class="feedback-bar" role="img" aria-label="${esc(p.title)}: ${fs.filter(f=>f.result==='Helpful').length} helpful, ${fs.filter(f=>f.result==='No change').length} no change, ${fs.filter(f=>f.result==='Uncomfortable').length} uncomfortable out of ${fs.length} responses">${['Helpful','No change','Uncomfortable'].map((r,i)=>`<i class="feedback-segment s${i}" style="width:${fs.filter(f=>f.result===r).length/fs.length*100}%"></i>`).join('')}</div><b>${fs.length}</b></div>`).join('')}</div><p class="chart-legend"><span>● Helpful</span><span>● No change</span><span>● Uncomfortable</span></p>`:'<div class="empty"><h3>Your experience will appear here.</h3><p>After a practice, choose optional feedback. Saving is always your choice.</p></div>'}${paired.length?`<p class="notice">Of ${paired.length} paired observations: ${paired.filter(f=>f.after>f.before).length} felt more settled, ${paired.filter(f=>f.after===f.before).length} the same, and ${paired.filter(f=>f.after<f.before).length} less settled. These observations cannot establish that a practice caused a change.</p>`:''}${[0,1,2,3].map(m=>{let fs=all.filter(f=>f.moment===m&&f.result==='Helpful');return fs.length?`<p class="insight-sentence">${fs.length} response${fs.length===1?'':'s'} marked helpful ${D.moments[m].title.toLowerCase()}. ${[...new Set(fs.map(f=>D.practices.find(p=>p.id===f.practiceId).title))].join(', ')}.</p>`:'';}).join('')}<details class="feedback-history"><summary>Explore or remove individual responses (${all.length})</summary>${[...all].reverse().slice(0,50).map(f=>`<article><div><strong>${D.practices.find(p=>p.id===f.practiceId).title} · ${f.result}</strong><small>${new Date(f.date).toLocaleString()} · ${D.moments[f.moment].title} · ${f.persistent?'Saved':'This visit'}</small></div><button class="text-button" data-adv="delete-feedback" data-id="${esc(f.id)}">Remove</button></article>`).join('')||'<p>No responses for this period.</p>'}</details><p class="small-note">The charts describe your entries. They are not health assessments, treatment outcomes or employer reports.</p></section>${preferencesHTML()}`;
 }
 function studioCard(s){return `<article class="studio-card"><div class="studio-card-top"><span class="studio-glyph">${icon(s.icon)}</span><span class="tag">${s.tag}</span></div><h3>${s.title}</h3><p>${s.description}</p><p class="studio-when"><strong>When to use:</strong> ${s.when}</p><div class="studio-card-bottom"><span>${s.steps.length} steps · Your pace</span><button type="button" class="text-button context-detail-link" data-context-open="studio:${s.id}" aria-haspopup="dialog" aria-controls="serein-context-panel" aria-expanded="false">How it works</button><button class="button button-teal" data-adv="studio" data-id="${s.id}">Enter studio →</button></div></article>`;}
 function studiosView(){return `<header class="page-header"><div><p class="eyebrow">SEREIN / INTERACTIVE STUDIOS</p><h1>Make the next step real.</h1><p class="page-sub">Six practical spaces to rehearse, prepare and take action. Drafts stay temporary unless you explicitly save a plan.</p></div></header><section class="studio-hero"><div><p class="eyebrow">FROM PERSONAL PAUSES TO PRACTICAL SUPPORT</p><h2>Find words.<br>Make room.<br><em>Change one thing.</em></h2><p>Choose a studio around the moment you are in. No patient information is needed.</p></div><div class="evidence-feature"><strong>6</strong><h3>actions for healthier workplaces</h3><p>NIOSH’s 2024 Impact Wellbeing Guide sets out six evidence-informed organizational actions. These six Serein studios are original educational tools, not the guide’s six actions.</p><a href="${A.references.niosh.url}" target="_blank" rel="noopener noreferrer">Read the source & scope ↗</a></div></section><div class="studio-grid">${A.studios.map(studioCard).join('')}</div><section class="context-stat"><strong>46%</strong><div><h3>Context deserves a date.</h3><p>U.S. health workers reporting burnout often or very often in the 2022 Quality of Worklife survey; published by CDC in 2023. A historical U.S. estimate, not a current local rate or a Serein outcome.</p><a href="${A.references.cdc.url}" target="_blank" rel="noopener noreferrer">Survey, population & limitations ↗</a></div></section>${plansHTML()}`;}
 function openStudio(id){let def=A.studios.find(s=>s.id===id);if(!def)return;studio={id,step:0,values:{},scenario:0,response:null,choice:'practical',teamPractice:'ground',teamDuration:120,external:true,result:''};studioRender();}
 function studioField(i){const s=A.studios.find(s=>s.id===studio.id),[label,placeholder]=s.fields[i];return `<label class="field-label" for="studio-field-${i}">${label}</label>`+(i===5&&s.id==='conditions'?`<input type="date" class="field" id="studio-field-${i}" data-studio-field="${i}" value="${esc(studio.values[i]||'')}">`:`<textarea rows="2" class="field" id="studio-field-${i}" data-studio-field="${i}" maxlength="1200" placeholder="${esc(placeholder)}">${esc(studio.values[i]||'')}</textarea>`);}
 function captureStudio(){if(!studio)return;$$('[data-studio-field]').forEach(e=>studio.values[e.dataset.studioField]=e.value.trim());const output=$('#studio-output');if(output)studio.result=output.value;}
 function studioRender(){
  const s=A.studios.find(s=>s.id===studio.id);let body='';
  if(studio.step===3){if(!studio.result)studio.result=buildStudioResult();body=`<div class="result-heading"><span class="studio-glyph">${icon('check')}</span><div><p class="eyebrow">A PRACTICAL NEXT STEP</p><h3>${s.result}</h3></div></div><label class="field-label" for="studio-output">Edit this so it sounds like you</label><textarea class="field studio-output" id="studio-output" rows="10" maxlength="12000">${esc(studio.result)}</textarea><div class="button-row"><button class="button button-teal" data-adv="studio-copy">Copy my ${s.id==='team'?'script':'plan'}</button><button class="button button-outline" data-adv="studio-download">Download text</button>${s.id==='conditions'?'<button class="text-button" data-adv="studio-save">Save this plan in this browser</button>':''}${s.id==='team'?'<button class="button button-outline" data-adv="team-present">Open shared presentation →</button>':''}${s.id==='difficult'&&studio.choice==='pause'?'<button class="button button-outline" data-practice="ground">Open a grounding pause →</button>':''}</div><p id="studio-result-status" class="small-note" role="status">Draft stays temporary. Nothing is sent to anyone. Keep names and patient details out of this space.</p>`;}
  else if(s.id==='boundary'){
   const q=A.scenarios[studio.scenario];
   if(studio.step===0)body=`<label class="field-label" for="boundary-scenario">A situation to rehearse</label><select class="field" id="boundary-scenario">${A.scenarios.map((q,i)=>`<option value="${i}" ${studio.scenario===i?'selected':''}>${q.title}</option>`).join('')}</select><p class="scenario-context">${q.context}</p><p class="notice">Use your professional responsibilities and workplace processes to guide real decisions.</p>`;
   if(studio.step===1)body=`<p class="studio-question">${q.context}</p><div class="response-options">${q.options.map(([t,r],i)=>`<button class="choice-card ${studio.response===i?'selected':''}" data-adv="boundary-response" data-value="${i}" aria-pressed="${studio.response===i}"><strong>${t}</strong>${studio.response===i?`<span class="response-rationale">${r}</span>`:''}</button>`).join('')}</div><p class="small-note">A rehearsal with explanatory feedback, not a competence assessment.</p>`;
   if(studio.step===2)body=s.fields.map((_,i)=>studioField(i)).join('');
  } else if(s.id==='difficult'){
   if(studio.step===0)body=`<p class="studio-question">Which kind of support would you choose?</p><div class="choice-grid">${[['practical','Practical help','Clarify responsibilities or available support.'],['pause','A quiet pause','Choose an outward focus, without retelling the event.'],['connection','Human connection','Prepare a conversation with someone trusted.']].map(([v,t,d])=>`<button class="choice-card ${studio.choice===v?'selected':''}" data-adv="difficult-choice" data-value="${v}" aria-pressed="${studio.choice===v}"><strong>${t}</strong><span>${d}</span></button>`).join('')}</div><p class="notice">You do not have to describe what happened. If immediate safety is at issue, use your workplace escalation or usual urgent-care route.</p>`;
   if(studio.step===1)body=studioField(0)+studioField(1);
   if(studio.step===2)body=studioField(2)+`<p class="notice">You can change your mind, decline reflection, or choose qualified support. Serein is not monitored.</p>`;
  } else if(s.id==='team'){
   if(studio.step===0)body=studioField(0)+`<p class="notice">Participation is optional. Offer observing, external focus, skipping and leaving without explanation.</p>`;
   if(studio.step===1)body=`<label class="field-label" for="team-practice">Shared practice</label><select class="field" id="team-practice">${D.practices.filter(p=>['ground','listen','tide','winddown'].includes(p.id)).map(p=>`<option value="${p.id}" ${studio.teamPractice===p.id?'selected':''}>${p.title}</option>`).join('')}</select><label class="field-label" for="team-duration">Available time</label><select id="team-duration" class="field">${[[60,'1 minute'],[120,'2 minutes'],[300,'5 minutes']].map(([n,l])=>`<option value="${n}" ${studio.teamDuration===n?'selected':''}>${l}</option>`).join('')}</select><p class="small-note">Grounding is self-paced. Other choices use the selected time.</p>`;
   if(studio.step===2)body=`<label class="check-label"><input type="checkbox" id="team-external" ${studio.external?'checked':''}>Use an external-focus cue throughout</label><p>Shared presentation starts in text view, with sound off, reduced motion and no breath holds. Participants may adapt or sit out.</p>${studioField(1)}`;
  } else {const fields=[0,1].map(i=>i+studio.step*2).filter(i=>i<s.fields.length);body=fields.map(studioField).join('');}
  openModal(s.title,`${studio.step===0?`<section class="studio-intro"><p>${s.description}</p><p><strong>Use it:</strong> ${s.when}</p><p><strong>Your choice:</strong> ${s.who}</p></section>`:''}${stepMeter(studio.step,4)}<div class="studio-step-title"><span class="tag">${s.tag}</span><h3>${s.steps[studio.step]}</h3></div>${body}<div class="studio-footer"><button class="button button-quiet" data-adv="studio-back" ${studio.step===0?'disabled':''}>Back</button>${studio.step<3?`<button class="button button-teal" data-adv="studio-next">${studio.step===2?'Build my draft':'Continue'} →</button>`:'<button class="button button-quiet" data-action="close-modal">Finish for now</button>'}</div><details class="studio-about"><summary>Background & sources</summary><p>${s.description} ${s.why}</p><p><strong>When:</strong> ${s.when}</p><p><strong>Who:</strong> ${s.who}</p>${sourceLinks(s.refs)}<p class="small-note">Original educational tool. No automatic sending, reporting, clinical assessment or supervision.</p></details>`);
  if(s.id==='conditions'&&studio.step===2&&$('#studio-field-5'))$('#studio-field-5').value=studio.values[5]||'';
 }
 function buildStudioResult(){const s=A.studios.find(s=>s.id===studio.id),v=i=>studio.values[i]||(s.fields[i]?'[Add: '+s.fields[i][0]+']':'[Agree together]');if(s.id==='boundary')return `Situation: ${A.scenarios[studio.scenario].title}\n\nI want to help within the priorities we agree. ${v(0)}\n\nCould we agree: ${v(1)}\n\nA check-back could be: ${v(2)}\n\nAdapt this to the role, urgency and workplace process.`;if(s.id==='support')return `I would like to discuss: ${v(0)}\n\nThe impact on my work is: ${v(1)}\n\nThe support I would like to request is: ${v(2)}\n\nCould we discuss this with: ${v(3)}\n\nA possible next step: ${v(4)}\n\nProposed review: ${v(5)}`;if(s.id==='transition')return `MY SHIFT TRANSITION\n\n□ Confirm through the approved handover: ${v(0)}\n□ Leave for the agreed next opportunity: ${v(1)}\n□ My transition action: ${v(2)}\n□ Make it easier by: ${v(3)}\n□ My recovery support: ${v(4)}\n□ Support available: ${v(5)}\n\nThis personal prompt does not replace handover or workplace records.`;if(s.id==='difficult')return `ONE NEXT STEP\n\nMy chosen focus: ${{practical:'Practical help',pause:'A quiet pause',connection:'Human connection'}[studio.choice]}\n\nPractical support: ${v(0)}\nA person or service I could contact: ${v(1)}\nWhen I could take this step: ${v(2)}\n\nI can choose a different step or qualified support. No event details or disclosure are required.`;if(s.id==='team')return `OPTIONAL TEAM PAUSE\n\nOpening: ${v(0)}\n\nPractice: ${D.practices.find(p=>p.id===studio.teamPractice).title}\nTiming: ${studio.teamPractice==='ground'?'Self-paced':durationLabel(studio.teamDuration)}\n\nOptions: observe, skip, keep eyes open, use external focus, or leave. Sound off, reduced motion, text-first presentation. ${studio.external?'External-focus cues selected.':''}\n\nClosing: ${v(1)}\n\nDo not ask participants to disclose private experiences. Nothing is monitored or assessed.`;return `WORKING CONDITIONS ACTION PLAN\n\nBarrier: ${v(0)}\nDesired improvement: ${v(1)}\nProposed change: ${v(2)}\nHow we will notice it happened: ${v(3)}\nProposed owner (to be agreed): ${v(4)}\nProposed review: ${studio.values[5]||'Agree a review date'}\n\nUse appropriate workplace approval and escalation. This app does not assign tasks or notify the proposed owner.`;}
 function plansHTML(){return `<section class="advance-panel"><div class="section-heading"><div><h2>Plans you chose to keep</h2><p>Saved in this browser without encryption. No plan is sent or monitored.</p></div></div>${store().savedPlans.length?store().savedPlans.map(p=>`<details class="saved-plan"><summary>${esc(A.studios.find(s=>s.id===p.studio)?.title||'Plan')} · ${new Date(p.date).toLocaleDateString()}</summary><pre>${esc(p.text)}</pre><button class="text-button" data-adv="delete-plan" data-id="${esc(p.id)}">Delete this plan</button></details>`).join(''):'<p>A Working Conditions plan can be saved explicitly from its result screen.</p>'}</section>`;}
 function journeysView(){return `<header class="page-header"><div><p class="eyebrow">LEARN / TRY / REFLECT / APPLY</p><h1>Small steps. Your own pace.</h1><p class="page-sub">Three flexible learning journeys. Fifteen short lessons. Your place is remembered without streaks or deadlines.</p></div></header><div class="journey-grid">${A.journeys.map(j=>{let done=(store().journeyProgress[j.id]||[]).length;return `<article class="journey-card"><img src="${D.images[j.image]}" alt="Illustrative ${j.image==='team'?'colleagues':'nature scene'}" loading="lazy"><div><p class="eyebrow">5 STEPS / FLEXIBLE ORDER</p><h2>${j.title}</h2><p>${j.description}</p><details class="journey-outline"><summary>View the five steps</summary><ol>${j.steps.map(step=>`<li>${esc(step.title)}</li>`).join('')}</ol></details><progress max="5" value="${done}" aria-label="${esc(j.title)}: ${done} of 5 steps marked complete"></progress><small>${done} of 5 marked complete</small><button class="button button-teal" data-adv="journey" data-id="${j.id}">${done===5?'Revisit':done?'Continue':'Begin exploring'} →</button></div></article>`;}).join('')}</div><section class="advance-panel"><h3>Learning that leaves room for life.</h3><p>You decide when a step is complete. Skipping or returning is welcome. This is educational progress, without accreditation or clinical assessment.</p><button class="text-button" data-adv="journey-reset-all">Reset learning progress</button></section>`;}
 function openJourney(id,index){let j=A.journeys.find(x=>x.id===id);if(!j)return;journey={id,index:index??j.steps.findIndex((_,i)=>!store().journeyProgress[id]?.includes(i))};if(journey.index<0)journey.index=0;journeyRender();}
 function journeyRender(){const j=A.journeys.find(x=>x.id===journey.id),s=j.steps[journey.index],done=store().journeyProgress[j.id]||[];let practice=s.practice;if(store().preferences.style==='nonbreath'&&D.practices.find(p=>p.id===practice)?.breathFocus)practice=s.alternative||'listen';openModal(j.title,`<div class="journey-step-nav" aria-label="Journey steps">${j.steps.map((x,i)=>`<button data-adv="journey-step" data-value="${i}" class="${i===journey.index?'active':''}" aria-label="${i+1}. ${esc(x.title)}${done.includes(i)?', marked complete':''}" ${i===journey.index?'aria-current="step"':''}>${done.includes(i)?'✓':i+1}</button>`).join('')}</div><p class="eyebrow">${s.kind} / STEP ${journey.index+1} OF ${j.steps.length}</p><h3>${s.title}</h3><p class="lesson-text">${s.text}</p>${s.action?`<p class="notice">${s.action}</p>`:''}<div class="button-row">${practice?`<button class="button button-outline" data-practice="${practice}">Try ${D.practices.find(p=>p.id===practice).title} →</button>`:''}${s.alternative&&s.alternative!==practice?`<button class="text-button" data-practice="${s.alternative}">Choose ${D.practices.find(p=>p.id===s.alternative).title}</button>`:''}${s.studio?`<button class="button button-outline" data-adv="studio" data-id="${s.studio}">Enter the studio →</button>`:''}</div><div class="studio-footer"><button class="button button-quiet" data-adv="journey-previous" ${journey.index===0?'disabled':''}>Previous</button><button class="button button-teal" data-adv="journey-complete">${done.includes(journey.index)?'Keep complete & continue':'Mark complete & continue'} →</button></div><button class="text-button" data-adv="journey-return">Return to journeys</button>${done.includes(journey.index)?'<button class="text-button unmark-step" data-adv="journey-unmark">Mark this step incomplete</button>':''}<p class="small-note">Your step marks are saved in this browser. You can revisit in any order.</p>${sourceLinks(j.id==='boundaries'?['who','niosh']:j.id==='transition'?['sleep','mindful']:['grounding','gentle'])}`);}
 function updateStage(s){let p=state.session?.practice;if(!p)return;const key=s.index+':'+Math.floor(s.elapsed/(state.session.phases().reduce((a,x)=>a+(x.seconds||0),0)||1));if(s.state==='playing'&&key!==chimePhase){chimePhase=key;if($('#session-chime')?.checked&&!state.preview&&audioContext?.state==='running'){const osc=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;osc.type='sine';osc.frequency.value=s.index%2?440:528;gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(.035,now+.04);gain.gain.exponentialRampToValueAtTime(.001,now+.4);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+.45);}}const stage=$('#player-stage');if(!$('#advance-stage'))stage.insertAdjacentHTML('beforeend','<div id="advance-stage" class="advance-stage" hidden></div>');const adv=$('#advance-stage');const map=p.id==='scan'&&state.visual==='map';const stones=p.id==='ground'&&state.visual!=='text';adv.hidden=!map&&!stones;
  const stageKey=p.id+':'+state.visual+(map?'':':'+s.index);const sameStage=adv.dataset.key===stageKey;adv.dataset.key=stageKey;
  if(map){$('#player-photo').hidden=true;$('#player-media-label').textContent='Attention map · not an anatomy assessment';adv.className='advance-stage body-attention';if(!sameStage)adv.innerHTML=`<svg viewBox="0 0 220 330" aria-hidden="true"><circle cx="110" cy="44" r="25"/><path d="M90 80 Q110 70 130 80 L145 160 L135 190 L133 290 L115 290 L110 210 L105 290 L87 290 L85 190 L75 160Z"/><path d="M89 85 L60 160 L66 190 M131 85 L160 160 L154 190"/></svg><div class="body-points">${[['Feet & support',0,84],['Legs',1,70],['Hands',2,55],['Shoulders',3,28],['Face',4,11],['Whole body',5,94]].map(([t,i,y])=>`<button data-player-step="${i}" class="${s.index===i?'active':''}" style="--point-y:${y}%" aria-current="${s.index===i?'step':'false'}">${t}</button>`).join('')}</div>`;}
  else if(stones){adv.className='advance-stage sensory-stage';if(!sameStage)adv.innerHTML=`<div class="sensory-symbol">${['◉','◈','≋','❋','◇'][s.index]}</div><span>NOTICE YOUR ACTUAL SURROUNDINGS</span>`;}
  if(map)adv.querySelectorAll('[data-player-step]').forEach(b=>{b.classList.toggle('active',+b.dataset.playerStep===s.index);b.setAttribute('aria-current',+b.dataset.playerStep===s.index?'step':'false');});
  if(p.id==='box'){let box=$('#box-guide');if(box){box.dataset.edge=String(state.session.noHolds?Math.floor((s.index+s.progress)*2)%4:s.index);let small=box.querySelector('small');if(small&&s.state==='playing'){let cycle=state.session.phases().reduce((a,x)=>a+x.seconds,0);small.textContent=`Cycle ${Math.floor(s.elapsed/cycle)+1} · Your comfortable pace`;}}}
 }
 function onPlay(){if($('#session-chime')?.checked){try{const C=global.AudioContext||global.webkitAudioContext;if(C){audioContext=audioContext||new C();audioContext.resume().catch(()=>{});}}catch{toast('Local tone unavailable. Text and visual guidance remain available.');}}}
 function quoteCount(){return D.reflections.length+A.quotes.filter(q=>q.moments.includes(state.moment)).length;}
 function quoteText(index){const list=[...D.reflections,...A.quotes.filter(q=>q.moments.includes(state.moment))];return list[index%list.length].text;}
 function heroImage(){return store().preferences.role==='Team leader'?D.images.team:[D.images.seated,D.frames.awareness[0],D.images.team,D.images.release][state.moment];}
 function sourceInfo(){openModal('Evidence, with its scope.',`<p>Each practice now has its own mapped background sources and adaptation notes. Source availability can change.</p>${sourceLinks(Object.keys(A.references))}<p class="notice">Editorial mapping updated ${A.updated}. Content is educational; product outcomes have not been clinically established.</p>`);}
 function reminders(){let online=location.protocol!=='file:';openModal('Your app, around your day.',`<section class="install-status"><p class="eyebrow">INSTALL / OFFLINE / REMINDERS</p><h3>Keep a little space close.</h3><p id="offline-status">${esc(offlineStatus())}</p><div class="button-row">${online?`<button class="button button-teal" id="offline-prepare" data-adv="offline" ${offlineBusy?'disabled':''}>${offlineReady?'Check offline content':'Make available offline'}</button><button class="button button-outline" data-adv="install">Install / add to home screen</button>`:''}</div><p id="install-note" class="small-note">Installation support varies. Your browser may offer Install, or Share → Add to Home Screen. Offline access stores app content on this device.</p></section><form id="reminder-form"><h3>A reminder you control.</h3><p>Download a calendar reminder for the shift days and time you choose. It works after import through your calendar, even when Serein is closed.</p><label class="field-label" for="reminder-title">Reminder title</label><input class="field" id="reminder-title" name="title" value="A little space for me" maxlength="80" required><label class="field-label" for="reminder-time">Local reminder time</label><input type="time" class="field" id="reminder-time" name="time" value="18:30" required><fieldset class="reminder-days"><legend>Repeat on</legend>${[['MO','Mon'],['TU','Tue'],['WE','Wed'],['TH','Thu'],['FR','Fri'],['SA','Sat'],['SU','Sun']].map(([v,l],i)=>`<label><input type="checkbox" name="days" value="${v}" ${i<5?'checked':''}>${l}</label>`).join('')}</fieldset><p class="small-note">Times follow the calendar’s local timezone. Choose days that fit your actual rota. Serein does not know your shifts or send push notifications.</p><p id="reminder-error" role="alert"></p><button type="submit" class="button button-teal">Download calendar reminder</button></form>`);}
 function makeReminder(form){
  const fd=new FormData(form),codes=['SU','MO','TU','WE','TH','FR','SA'],days=[...new Set(fd.getAll('days').filter(d=>codes.includes(d)))],time=String(fd.get('time')),title=String(fd.get('title')||'').trim();
  const [h,m]=time.split(':').map(Number);if(!days.length||!/^\d\d:\d\d$/.test(time)||h>23||m>59||!title){$('#reminder-error').textContent='Choose at least one day, a title and a valid time.';return;}
  const d=new Date();d.setHours(h,m,0,0);if(d<=new Date())d.setDate(d.getDate()+1);while(!days.includes(codes[d.getDay()]))d.setDate(d.getDate()+1);
  const pad=n=>String(n).padStart(2,'0'),stamp=d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'T'+pad(h)+pad(m)+'00';
  const clean=t=>t.replace(/\\/g,'\\\\').replace(/[\r\n]+/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
  const fold=line=>{let out='',row='',bytes=0;for(const ch of line){const n=new TextEncoder().encode(ch).length;if(bytes+n>75){out+=row+'\r\n';row=' ';bytes=1;}row+=ch;bytes+=n;}return out+row;};
  const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//HCA//Serein//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+c.uid()+'@serein.hca','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+stamp,'DURATION:PT2M','RRULE:FREQ=WEEKLY;BYDAY='+days.join(','),'SUMMARY:'+clean(title),'DESCRIPTION:An optional Serein pause. Change or delete this reminder in your calendar.','BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:'+clean(title),'END:VALARM','END:VEVENT','END:VCALENDAR',''];
  download(lines.map(fold).join('\r\n'),'Serein-reminder.ics','text/calendar');$('#reminder-error').textContent='Calendar file prepared. Import it into your calendar and check the days and time.';
 }

 function portableDistribution(){return document.querySelector('meta[name="serein-distribution"]')?.content==='portable';}
 function shellURL(){const url=new URL(portableDistribution()?location.href:'./index.html',location.href);url.hash='';url.search='';return url;}
 function offlineStatus(){if(location.protocol==='file:')return 'This single HTML already includes its core content and works offline. Installation requires HTTPS hosting with sw.js beside the HTML.';return offlineMessage||(offlineBusy?'Preparing offline content…':offlineReady?'Offline content is ready on this device.':'Use the hosted edition online first, then choose to save its content for offline use.');}
 function refreshOfflineStatus(){const status=$('#offline-status'),button=$('#offline-prepare');if(status)status.textContent=offlineStatus();if(button){button.disabled=offlineBusy;button.textContent=offlineReady?'Check offline content':'Make available offline';}}
 function bounded(promise){let timeout;return Promise.race([promise,new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error('Request timed out')),15000);})]).finally(()=>clearTimeout(timeout));}
 async function prepareOffline(){
  if(!('serviceWorker'in navigator)||!/^https?:$/.test(location.protocol)||!('caches'in global)){offlineMessage='Offline installation requires a supported browser on HTTPS. The downloadable HTML already contains its core content.';refreshOfflineStatus();toast(offlineMessage);return;}
  offlineBusy=true;offlineMessage='';refreshOfflineStatus();
  try{
   const workerURL=new URL('./sw.js',location.href),shell=shellURL();if(portableDistribution())workerURL.searchParams.set('shell',shell.pathname.split('/').pop());
   const check=await bounded(fetch(workerURL.href,{cache:'no-store'})),workerText=check.ok?await check.text():'';if(!check.ok||!/^\s*\/\*\s*SEREIN_OFFLINE_WORKER\b/.test(workerText)){offlineMessage='Offline helper sw.js is missing from this host. Upload the supplied sw.js beside this HTML, or use the hosted Serein edition. The app remains available online.';toast(offlineMessage);return;}
   registration=await bounded(navigator.serviceWorker.register(workerURL.href));await bounded(navigator.serviceWorker.ready);
   const config=portableDistribution()?{cacheName:document.querySelector('meta[name="serein-offline-cache"]')?.content,files:[shell.href]}:await fetch('./offline-assets.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Asset list unavailable');return r.json();});
   if(!config.cacheName)throw Error('Offline cache configuration missing');const cache=await caches.open(config.cacheName);await bounded(cache.addAll(config.files));offlineReady=!!await cache.match(shell.href);if(!offlineReady)throw Error('Offline content incomplete');toast('App content is ready offline on this device.');
  }catch{offlineMessage='Offline setup could not finish. Check your connection, HTTPS hosting and available device storage, then try again.';toast(offlineMessage);}
  finally{offlineBusy=false;refreshOfflineStatus();}
 }

 function install(){if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>installPrompt=null);}else if($('#install-note'))$('#install-note').textContent=window.matchMedia?.('(display-mode: standalone)').matches?'Serein is already running as an installed app.':'Use your browser’s Install option, or Share → Add to Home Screen. If unavailable, keep using the browser edition.';}
 function initialize(){applyComfort();window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});if('caches'in global)caches.keys().then(async keys=>{for(const key of keys.filter(k=>portableDistribution()?k===document.querySelector('meta[name="serein-offline-cache"]')?.content:k.startsWith('serein-hca-v4-'))){const cache=await caches.open(key);if(await cache.match(shellURL().href)){offlineReady=true;break;}}}).catch(()=>{});navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='UPDATE_AVAILABLE')toast('An updated edition is available. Reconnect and use “Check for updates” in My app.');});}
 function appHTML(){return `<section class="advance-panel app-panel"><p class="eyebrow">SEREIN / ON YOUR DEVICE</p><h3>Ready when a pause is possible.</h3><p>The downloadable edition includes its core content. The hosted edition can be installed and explicitly prepared for offline use.</p><div class="button-row"><button class="button button-teal" data-adv="app-options">Install, offline & reminders →</button><button class="text-button" data-adv="app-update">Check for updates</button></div><p class="small-note">Personal data stays in this browser. Different browsers and the standalone file have separate storage; use export/import to transfer your data.</p></section>`;}
 async function checkUpdates(){if(!('serviceWorker'in navigator)||location.protocol==='file:'){toast('Use the hosted edition to check for app updates.');return;}try{const regs=await navigator.serviceWorker.getRegistrations();if(!regs.length){toast('Prepare offline access first, or reload online for the latest app.');return;}for(const r of regs){await r.update();if(r.waiting){openModal('An update is ready.',`<p>Export anything you want to keep, then apply the update. Unsaved visit-only entries disappear on reload. Journal drafts remain in this tab when temporary storage is available.</p><div class="button-row"><button class="button button-outline" data-action="export">Export first</button><button class="button button-teal" data-adv="apply-update">Apply update & reload</button></div>`);registration=r;return;}}toast('Update check complete. Reload online to use the latest published edition.');}catch{toast('Update check unavailable. Try again while online.');}}
 async function copyText(text,id){try{await navigator.clipboard.writeText(text);$(id).textContent='Copied. Nothing was sent.';}catch{$('#studio-output')?.select();$(id).textContent='Select the draft and copy it using your device controls.';}}
 async function handle(b){const d=b.dataset,a=d.adv;if(!a)return false;
  if(a==='finder')finderOpen();
  else if(a==='finder-moment'){finder.moment=+d.value;finderRender();}
  else if(a==='finder-time'){finder.budget=d.value==='self'?'self':+d.value;finderRender();}
  else if(a==='finder-next'){finder.step=Math.min(3,finder.step+1);finderRender();}
  else if(a==='finder-back'){finder.step=Math.max(0,finder.step-1);finderRender();}
  else if(a==='finder-start'){let p=D.practices.find(p=>p.id===d.id);state.moment=finder.moment;openPractice(p.id,chooseDuration(p,finder.budget==='self'?0:+finder.budget));if(finder.silent){state.voice=false;$('#session-voice').checked=false;$('#session-chime').checked=false;}}
  else if(a==='evidence')evidence(d.id);
  else if(a==='explain')openModal(d.title,`<p>${esc(d.text)}</p>`);
  else if(a==='studios-open')navigate('studios');
  else if(a==='journeys-open')navigate('journeys');
  else if(a==='preferences-open'){state.spaceTab='patterns';closeModal();navigate('space');}
  else if(a==='feedback')feedback(d.value);
  else if(a==='practice-choice')choosePreference(d.id,d.value);
  else if(a==='restore-practice'){delete store().practiceMemory[d.id];delete store().practiceChoices[d.id];persist();render();}
  else if(a==='delete-feedback'){let i=store().feedback.findIndex(f=>f.id===d.id);if(i>=0){let [f]=store().feedback.splice(i,1);persist();render();toast('Response removed.',()=>{store().feedback.splice(i,0,f);persist();render();});}}
  else if(a==='studio')openStudio(d.id);
  else if(a==='studio-next'){captureStudio();studio.step++;studioRender();}
  else if(a==='studio-back'){captureStudio();studio.step--;studio.result='';studioRender();}
  else if(a==='boundary-response'){studio.response=+d.value;studioRender();}
  else if(a==='difficult-choice'){studio.choice=d.value;studioRender();}
  else if(a==='studio-copy'){captureStudio();await copyText(studio.result,'#studio-result-status');}
  else if(a==='studio-download'){captureStudio();download(studio.result,`Serein-${studio.id}-plan.txt`,'text/plain');}
  else if(a==='studio-save'){captureStudio();const id=studio.savedId||c.uid(),plan={id,studio:studio.id,text:studio.result,date:new Date().toISOString()};let i=store().savedPlans.findIndex(x=>x.id===id);if(i<0)store().savedPlans.push(plan);else store().savedPlans[i]=plan;studio.savedId=id;persist();$('#studio-result-status').textContent='Plan saved in this browser without encryption. You can delete it in Studios. Nothing was sent.';}
  else if(a==='delete-plan'){store().savedPlans=store().savedPlans.filter(p=>p.id!==d.id);persist();render();}
  else if(a==='team-present'){captureStudio();pendingTeam={external:studio.external};let p=D.practices.find(p=>p.id===studio.teamPractice);openPractice(p.id,chooseDuration(p,studio.teamDuration));}
  else if(a==='journey')openJourney(d.id);
  else if(a==='journey-step'){journey.index=+d.value;journeyRender();}
  else if(a==='journey-previous'){journey.index--;journeyRender();}
  else if(a==='journey-return'){closeModal();navigate('journeys');}
  else if(a==='journey-complete'){let done=store().journeyProgress[journey.id]||[];if(!done.includes(journey.index))done.push(journey.index);store().journeyProgress[journey.id]=done;persist();if(journey.index<A.journeys.find(j=>j.id===journey.id).steps.length-1){journey.index++;journeyRender();}else{closeModal();navigate('journeys');toast('Your step is marked complete. Revisit whenever useful.');}}
  else if(a==='journey-unmark'){store().journeyProgress[journey.id]=store().journeyProgress[journey.id].filter(i=>i!==journey.index);persist();journeyRender();}
  else if(a==='journey-reset-all')openModal('Reset learning progress?',`<p>This removes your journey step marks. Your reflections, plans and practice choices remain available.</p><button class="button button-outline" data-adv="journey-reset-confirm">Reset step marks</button>`);
  else if(a==='journey-reset-confirm'){store().journeyProgress={};persist();closeModal();render();}
  else if(a==='app-options')reminders();
  else if(a==='offline')await prepareOffline();
  else if(a==='install')install();
  else if(a==='app-update')await checkUpdates();
  else if(a==='apply-update'){navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});registration?.waiting?.postMessage({type:'SKIP_WAITING'});}
  else if(a==='sources')sourceInfo();
  else return false;
  return true;
 }
 function onChange(e){let id=e.id;if(id==='finder-style')finder.style=e.value;if(id==='finder-position')finder.position=e.value;if(id==='finder-silent')finder.silent=e.checked;if(id==='boundary-scenario'){studio.scenario=+e.value;studio.response=null;studioRender();}if(id==='team-practice')studio.teamPractice=e.value;if(id==='team-duration')studio.teamDuration=+e.value;if(id==='team-external')studio.external=e.checked;
  if(id==='session-before'&&sessionMeta)sessionMeta.before=+e.value||null;
  if(id==='session-after'&&sessionMeta){sessionMeta.after=+e.value||null;upsertFeedback();}
  if(id==='feedback-save'&&sessionMeta){sessionMeta.persistent=e.checked;upsertFeedback();if(sessionMeta.result)feedback(sessionMeta.result);}
 }
 function addedSearch(query){let q=query.trim().toLowerCase(),ss=A.studios.filter(s=>(s.title+' '+s.description).toLowerCase().includes(q)),js=A.journeys.filter(j=>(j.title+' '+j.description).toLowerCase().includes(q));return `<p class="search-group-label">STUDIOS & JOURNEYS</p>${ss.map(s=>`<button class="search-result" data-adv="studio" data-id="${s.id}">${icon(s.icon)}<span><strong>${s.title}</strong><small>Interactive studio</small></span><span>↗</span></button>`).join('')}${js.map(j=>`<button class="search-result" data-adv="journey" data-id="${j.id}">${icon('book')}<span><strong>${j.title}</strong><small>Five-step learning journey</small></span><span>↗</span></button>`).join('')}`;}
 return {resetFeedback,rank,finderOpen,aboutHTML,preferencesHTML,plansHTML,openStudio,openJourney,initialize,applyComfort,comfortForm,comfortValues,recommend,reason,homeExtras,evidenceButton,preparePractice,rememberPractice,insights,studiosView,journeysView,appHTML,updateStage,handle,onChange,addedSearch,sourceInfo,makeReminder,onPlay,quoteCount,quoteText,heroImage,get sessionMeta(){return sessionMeta;},get studio(){return studio;},get finder(){return finder;}};
}
global.Serein.toolsFactory={normalize,create};
})(globalThis);
